import sys
input = sys.stdin.readline

def prefix_function(s):
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        k = pi[i - 1]
        while k and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    return pi

def info(x, y):
    pi = prefix_function(y + "#" + x)
    return (len(y) in pi), pi[-1]

a = input().strip()
b = input().strip()

inside_ab, ov_ab = info(a, b)
inside_ba, ov_ba = info(b, a)
if inside_ab:
    print(len(a))
elif inside_ba:
    print(len(b))
else:
    print(len(a) + len(b) - max(ov_ab, ov_ba))

